-- AD7 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD7.sql.
SELECT 'both case tables exist with RLS enabled and forced' AS rule, (SELECT count(*) FROM pg_class c JOIN pg_namespace s ON s.oid=c.relnamespace WHERE s.nspname='desk' AND c.relname IN ('fadm_case','fadm_case_event') AND c.relrowsecurity AND c.relforcerowsecurity) = 2 AS ok
UNION ALL SELECT 'case events are append-only (update, delete, truncate triggers)', (SELECT count(*) FROM pg_trigger WHERE tgrelid='desk.fadm_case_event'::regclass AND tgname IN ('fadm_case_event_frozen','fadm_case_event_frozen_t')) = 2
UNION ALL SELECT 'the status machine trigger guards the case', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='desk.fadm_case'::regclass AND tgname='fadm_case_00guard')
UNION ALL SELECT 'Priority Support is a support-queue label with a clock exactly when it is set (constraints)', (SELECT count(*) FROM pg_constraint WHERE conrelid='desk.fadm_case'::regclass AND contype='c' AND (pg_get_constraintdef(oid) ILIKE '%priority%')) >= 2
UNION ALL SELECT 'billing cases are always restricted (constraint)', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='desk.fadm_case'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%billing%' AND pg_get_constraintdef(oid) ILIKE '%restricted%')
UNION ALL SELECT 'one case per address and thread', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='desk.fadm_case'::regclass AND contype='u' AND pg_get_constraintdef(oid) ILIKE '%address%thread_id%')
UNION ALL SELECT 'the case table has no money column', NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='desk' AND table_name IN ('fadm_case','fadm_case_event') AND column_name ~* '(price|amount|invoice|card|refund|currency)')
UNION ALL SELECT 'case.read has a bulk-viewing breaker', EXISTS (SELECT 1 FROM desk.fadm_burst_limit WHERE action='case.read')
UNION ALL SELECT 'case ledger kinds are on the closed list', (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('case.ingest','case.assign','case.status','case.reply')) = 4
UNION ALL SELECT 'desk_app has no direct right on the case tables', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid=c.relnamespace WHERE s.nspname='desk' AND c.relname IN ('fadm_case','fadm_case_event') AND (has_table_privilege('desk_app',c.oid,'SELECT') OR has_table_privilege('desk_app',c.oid,'INSERT') OR has_table_privilege('desk_app',c.oid,'UPDATE') OR has_table_privilege('desk_app',c.oid,'DELETE')))
UNION ALL SELECT 'the five case doors are granted to desk_app', has_function_privilege('desk_app','desk.fadm_case_ingest(text,text,text,text,boolean)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_case_list(uuid,text,text,int,inet)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_case_assign(uuid,uuid,uuid,inet)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_case_status(uuid,uuid,text,inet)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_case_reply(uuid,uuid,inet)','EXECUTE')
UNION ALL SELECT 'the permission helper is not callable by desk_app', NOT has_function_privilege('desk_app','desk.fadm_case_can(uuid,desk.fadm_case,text,inet)','EXECUTE')
UNION ALL SELECT 'all SECURITY DEFINER functions pin search_path', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid=p.pronamespace WHERE s.nspname='desk' AND p.prosecdef AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')))
UNION ALL SELECT 'ledger hash chain still verifies', desk.fadm_ledger_verify();
